export type ExampleSaveKey =
	| 'basic'
	| 'idle'
	| 'active'
	| 'transcension'
	| 'fullRoster'
	| 'relics'
	| 'allRarities'
	| 'mobile'
	| 'desktop';

export interface ExampleSave {
	/** Button label, under `editor.exampleSaves` in the messages. */
	key: ExampleSaveKey;
	save: string;
}

export const examples: ExampleSave[] = [
	{
		key: 'basic',
		save: ''
	},
	{
		key: 'idle',
		save: ''
	},
	{
		key: 'active',
		save: ''
	}
];

export const transcensionExamples: ExampleSave[] = [
	{
		key: 'transcension',
		save: ''
	}
];

/**
 * The `examples` saves above have an empty mercenary roster, so the mercenary
 * viewer reuses the fully populated save instead.
 */
export const mercenaryExamples: ExampleSave[] = transcensionExamples.map((example) => ({
	...example,
	key: 'fullRoster'
}));

/**
 * The `examples` saves above have no relics either, so the relic tools reuse
 * the transcension save, plus a copy of it holding one relic of each rarity
 * (Legendary to Epic equipped, Rare on the junk pile, Common and Uncommon in
 * no slot).
 */
export const relicExamples: ExampleSave[] = [
	...transcensionExamples.map((example): ExampleSave => ({
		...example,
		key: 'relics'
	})),
	{
		key: 'allRarities',
		save: ''
	}
];

export const saveConverterExamples: ExampleSave[] = [
	{
		key: 'mobile',
		save: ''
	},
	{
		key: 'desktop',
		save: ''
	}
];
